package com.ivanwitt.mayasunmoon

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/**
 * Clean cloud/temple scenery with the painted sun removed.
 * Embedded in the APK so lighting remains fully offline.
 */
object SceneryAssets {
    @Volatile private var cachedMaster: Bitmap? = null

    fun masterBitmap(): Bitmap = cachedMaster ?: synchronized(this) {
        cachedMaster ?: decode(MASTER_WEBP).also { cachedMaster = it }
    }

    private fun decode(encoded: String): Bitmap {
        val data = Base64.decode(encoded, Base64.DEFAULT)
        return requireNotNull(BitmapFactory.decodeByteArray(data, 0, data.size)) {
            "Unable to decode embedded scenery artwork"
        }
    }

